/*
 * Port-only: data the original kept inside ALIFE.EXE, looked up the way the
 * EXE's own code finds it: by resource type/id or by virtual address.
 *
 * Texts and number tables of .rdata/.data are compiled in from src/data/
 * (generated by tools/extract_exe.py, see data/exe_data.h) and need no EXE.
 * Image data is read from the user's ALIFE.EXE at runtime: the PE resources
 * (cursors, the icon) and the image regions of .data (the built-in font),
 * which exe_res_va only returns once exe_res_open has loaded the EXE.
 */
#ifndef AFTERLIFE_GFX_EXE_RES_H
#define AFTERLIFE_GFX_EXE_RES_H

#include <stdbool.h>
#include <stdint.h>

#define EXE_RT_CURSOR 1
#define EXE_RT_GROUP_CURSOR 12

/* Loads `name` (looked up in the data dir) once; later calls are no-ops.
 * Returns false if it isn't there or isn't a PE image. */
bool exe_res_open(const char *name);
void exe_res_close(void);

/* Data of resource type/id (first language) from the loaded EXE, or NULL. */
const uint8_t *exe_res_find(uint32_t type, uint32_t id, uint32_t *size);
/* Bytes at virtual address `va` of the image (.rdata and .data only), with
 * *avail bytes readable up to the end of its section's file data. NULL if
 * not mapped, or in an image region while the EXE isn't loaded. */
const uint8_t *exe_res_va(uint32_t va, uint32_t *avail);

#endif
